<script lang="ts">
 import {page} from '$app/stores';import ProjectDatabase from '$lib/components/database/ProjectDatabase.svelte';import Heading from '$lib/components/Heading.svelte';import Icon from '$lib/components/Icon.svelte';import Status from '$lib/components/Status.svelte';import Unmigrated from '$lib/components/Unmigrated.svelte';import {workspace,connectDomain,disconnectDomain,deploy,rollback} from '$lib/stores/workspace';import {projectTabs} from '$lib/navigation';
 let domain='',image='',error='';let showConnect=false,confirmed=false;
 $: key=$page.params.id||'';$: tab=$page.params.tab||'overview';$: p=$workspace.projects.find(x=>x.id===key);$: ds=$workspace.domains.filter(d=>d.project===key);$: available=$workspace.domains.filter(d=>!d.project);$: path='/projects/'+key;
 function run(fn:()=>void){try{error='';fn()}catch(e){error=e instanceof Error?e.message:'Action failed.'}}
 const resources=[['Domains','Domains','Connect your own address'],['Database','Databases','Connect or create a database'],['Environment','Code','Manage application variables'],['Files','File Manager','Explore source files'],['Backups','Backups','Protect your project']];
</script>
{#if p}<Heading title={p.name} subtitle={p.framework+' · '+p.source+' · Demo project'}><Status value={p.status}/></Heading><nav class="tabs native-tabs" aria-label="Project sections">{#each projectTabs as label}<a class:active={tab===label.toLowerCase()} class="tab" aria-current={tab===label.toLowerCase()?'page':undefined} href={path+'/'+label.toLowerCase()}>{label}</a>{/each}</nav>{#if error}<p role="alert" class="error">{error}</p>{/if}
{#if tab==='overview'}<div class="stack"><div class="split"><div class="stack"><section class="card"><h3>Project setup</h3><p class="subtitle">Everything you need to get your application online.</p>{#each [['Repository & application',true,'Project configuration saved'],['Build & deployment',p.status==='Live',p.status==='Live'?'Sample deployment is live':'Prepare your first deployment'],['Website address',ds.length>0,ds.length?'Domain connected to the project':'Connect an available address'],['HTTPS security',ds.some(d=>d.ssl),'Secure the website after DNS and deployment checks']] as row,i}<div class="checkline"><span class:complete={!!row[1]} class="step-icon">{#if row[1]}<Icon name="Check"/>{:else}{i+1}{/if}</span><div class="grow"><strong class="strong">{row[0]}</strong><p class="muted">{row[2]}</p></div></div>{/each}</section><section class="card"><h3>Website addresses</h3>{#each ds as d}<div class="setting-row"><span class="strong native-path">{d.name}</span><Status value={d.status}/></div>{:else}<p class="subtitle">No connected address.</p>{/each}</section></div><section class="card"><h3>Configuration</h3><div class="summary-list">{#each [['Source',p.source],['Repository / image',p.repo],['Branch',p.branch],['Application type',p.framework],['Memory',p.ram+' MiB'],['CPU',p.cpu+'% of one core'],['Internal port',p.port]] as r}<div><span class="muted">{r[0]}</span><strong>{r[1]}</strong></div>{/each}</div></section></div><section class="card"><h3>Extend your project</h3><p class="subtitle" style="margin-bottom:16px">Connect resources when your application needs them.</p><div class="deploy-resource-grid">{#each resources as r}<a class="feature" href={path+'/'+r[0].toLowerCase()} style="text-decoration:none"><Icon name={r[1]}/><span><strong>{r[0]}</strong><small>{r[2]}</small></span></a>{/each}</div></section></div>
{:else if tab==='deployments'}<div class="stack"><section class="card stack"><div><h3>Deployment status</h3><p class="subtitle">Simulated release history. No image is pulled or routed.</p></div><form class="native-inline" on:submit|preventDefault={()=>run(()=>deploy(key,image||'nginx:alpine'))}><label class="field grow">Container image<input placeholder="nginx:alpine" bind:value={image}/></label><button class="btn primary" type="submit" style="align-self:end">Simulate deployment</button></form></section><section class="card table-card"><div class="table-head"><div class="row between wrap"><h3>Release history</h3><button class="btn secondary" disabled={p.releases.length<2} on:click={()=>confirmed=true}>Roll back</button></div>{#if confirmed}<div class="callout"><strong>Restore the previous demo image?</strong><p>This creates another simulated release.</p><div class="native-inline"><button class="btn primary small" on:click={()=>{run(()=>rollback(key));confirmed=false}}>Confirm rollback</button><button class="btn secondary small" on:click={()=>confirmed=false}>Cancel</button></div></div>{/if}</div><div class="table-wrap"><table><thead><tr><th>Image</th><th>Action</th><th>Created</th><th>Status</th></tr></thead><tbody>{#each p.releases as r}<tr><td class="mono native-path">{r.image}</td><td>{r.kind}</td><td>{new Date(r.date).toLocaleString()}</td><td><Status value={p.activeRelease===r.id?'Active':'Succeeded'}/></td></tr>{:else}<tr><td colspan="4">No native demo releases yet.</td></tr>{/each}</tbody></table></div></section></div>
{:else if tab==='logs'}<section class="card stack"><h3>Application logs</h3><pre class="native-log mono">[DEMO] Project: {p.name}{'\n'}[DEMO] Runtime: {p.framework}{'\n'}[DEMO] Status: {p.status}{'\n'}{p.releases.length?'[DEMO] Latest image: '+p.releases[0].image+'\n':''}[DEMO] No real process is running.</pre></section>
{:else if tab==='domains'}<section class="card table-card"><div class="table-head"><div class="row between wrap"><div><h3>Connected domains</h3><p class="subtitle">Choose an available workspace hostname.</p></div><button class="btn primary" on:click={()=>showConnect=!showConnect}><Icon name="Plus"/>Connect domain</button></div>{#if showConnect}<form class="native-inline" style="margin:16px 0" on:submit|preventDefault={()=>run(()=>{connectDomain(key,domain);domain='';showConnect=false})}><label class="field grow">Available domain<select bind:value={domain} required><option value="">Select a domain</option>{#each available as d}<option value={d.id}>{d.name}</option>{/each}</select></label><button class="btn primary" type="submit" disabled={!domain} style="align-self:end">Connect</button><a href="/domains" class="btn secondary" style="align-self:end">Add domain</a></form>{/if}</div><div class="table-wrap"><table><thead><tr><th>Domain / subdomain</th><th>Status</th><th>SSL certificate</th><th>Actions</th></tr></thead><tbody>{#each ds as d}<tr><td class="native-path">{d.name}</td><td><Status value={d.status}/></td><td><Status value={d.ssl?'Secured':'Not issued'}/></td><td>{#if !d.system}<button class="btn secondary small" on:click={()=>run(()=>disconnectDomain(key,d.id))}>Disconnect</button>{/if}</td></tr>{:else}<tr><td colspan="4">No connected domains.</td></tr>{/each}</tbody></table></div></section>
{:else if tab==='database'}<ProjectDatabase projectId={key}/>{:else}<Unmigrated name={tab[0].toUpperCase()+tab.slice(1)}/>{/if}
{:else}<Heading title="Project not found" subtitle="This project is not in your demo workspace."/><a class="btn secondary" href="/projects">All projects</a>{/if}
